import multiprocessing
import cryptography.hazmat.bindings._rust as rust_bindings

def do_encrypt(key, nonce, plaintext, associated_data):
    aesgcm = rust_bindings.openssl.aead.AESGCM(key)
    return aesgcm.encrypt(nonce, plaintext, associated_data)

class Solver:
    def __init__(self):
        self.pool = multiprocessing.Pool(1)

    def solve(self, problem, **kwargs):
        key = problem["key"]
        nonce = problem["nonce"]
        plaintext = problem["plaintext"]
        associated_data = problem["associated_data"]

        ciphertext = self.pool.apply(do_encrypt, (key, nonce, plaintext, associated_data))

        actual_ciphertext = ciphertext[:-16]
        tag = ciphertext[-16:]

        return {"ciphertext": actual_ciphertext, "tag": tag}
